import base64, os, re

favicon_ico_b64 = """"""

icon_png_b64 = """"""

apple_icon_png_b64 = """"""


# === 1. Replace favicon files ===
with open("app/favicon.ico", "wb") as f:
    f.write(base64.b64decode(favicon_ico_b64))
print("Updated app/favicon.ico")

with open("app/icon.png", "wb") as f:
    f.write(base64.b64decode(icon_png_b64))
print("Updated app/icon.png")

with open("app/apple-icon.png", "wb") as f:
    f.write(base64.b64decode(apple_icon_png_b64))
print("Updated app/apple-icon.png")

# === 2. Update meta title in layout.tsx ===
layout_path = "app/layout.tsx"
if os.path.exists(layout_path):
    with open(layout_path, "r") as f:
        content = f.read()
    # Replace the title
    new_content = content.replace("ZAND — Rooted Living", "Zand - Learn, Explore, Connect")
    new_content = new_content.replace("ZAND \\u2014 Rooted Living", "Zand - Learn, Explore, Connect")
    # Also catch variations
    new_content = new_content.replace("ZAND - Rooted Living", "Zand - Learn, Explore, Connect")
    if new_content != content:
        with open(layout_path, "w") as f:
            f.write(new_content)
        print(f"Updated title in {layout_path}")
    else:
        print(f"Title pattern not found in {layout_path}, checking other files...")

# Also check all page files for the title in generateMetadata
for root, dirs, files in os.walk("app"):
    for fname in files:
        if fname.endswith(".tsx") or fname.endswith(".ts"):
            fpath = os.path.join(root, fname)
            with open(fpath, "r") as f:
                content = f.read()
            new_content = content
            for old in ["ZAND — Rooted Living", "ZAND \\u2014 Rooted Living", "ZAND - Rooted Living"]:
                new_content = new_content.replace(old, "Zand - Learn, Explore, Connect")
            if new_content != content:
                with open(fpath, "w") as f:
                    f.write(new_content)
                print(f"Updated title in {fpath}")

print("\nDone! Now run:")
print('npx next build && git add -A && git commit -m "Bigger favicon + update meta title" && git push')
